import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.BgftbQsK.js";const k=JSON.parse('{"title":"First Boot & Essential Setup","description":"Essential post-installation steps: system updates, installing tools, preventing laptop sleep on lid close, hostname, timezone, and editor configuration.","frontmatter":{"title":"First Boot & Essential Setup","order":3,"description":"Essential post-installation steps: system updates, installing tools, preventing laptop sleep on lid close, hostname, timezone, and editor configuration.","head":[["meta",{"name":"og:title","content":"First Boot & Essential Setup | Ubuntu Home Lab Server"}],["meta",{"property":"og:description","content":"Essential post-installation steps: system updates, installing tools, preventing laptop sleep on lid close, hostname, timezone, and editor configuration."}]]},"headers":[],"relativePath":"chapters/03-first-boot-essential-setup.md","filePath":"chapters/03-first-boot-essential-setup.md","lastUpdated":null}'),t={name:"chapters/03-first-boot-essential-setup.md"};function l(p,s,h,o,r,d){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h2 id="what-happens-when-linux-boots" tabindex="-1">What Happens When Linux Boots <a class="header-anchor" href="#what-happens-when-linux-boots" aria-label="Permalink to &quot;What Happens When Linux Boots&quot;">​</a></h2><p>Understanding the boot sequence helps you troubleshoot problems:</p><ol><li><strong>UEFI firmware</strong> reads <code>/boot/efi</code> → finds the GRUB bootloader</li><li><strong>GRUB</strong> loads the Linux kernel from <code>/boot/vmlinuz</code></li><li><strong>Kernel</strong> initializes hardware, mounts root filesystem</li><li><strong>systemd</strong> (PID 1) starts all services in parallel</li><li><strong>Login prompt</strong> appears</li></ol><h2 id="first-login" tabindex="-1">First Login <a class="header-anchor" href="#first-login" aria-label="Permalink to &quot;First Login&quot;">​</a></h2><p>After installation, you&#39;ll see a text login prompt. Type your username and password (password is invisible — this is normal in Linux, it&#39;s not broken).</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">homelab</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labadmin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Password:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ████████</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   ←</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> you</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> won&#39;t see anything, just type it</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="essential-first-commands" tabindex="-1">Essential First Commands <a class="header-anchor" href="#essential-first-commands" aria-label="Permalink to &quot;Essential First Commands&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Always do this first — update everything</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Why both commands? <code>apt update</code> refreshes the package list from Ubuntu&#39;s servers. <code>apt upgrade</code> actually downloads and installs the updates. They&#39;re separate because sometimes you want to check what&#39;s available before installing.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install essential tools</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  htop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iotop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nethogs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  build-essential</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  net-tools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  tree</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  neofetch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vim</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>What these do:</p><ul><li><code>curl wget</code> — Download files from the internet (you&#39;ll use these constantly)</li><li><code>git</code> — Version control (you know this one)</li><li><code>htop</code> — Interactive process viewer (better than <code>top</code>)</li><li><code>iotop</code> — Disk I/O monitor per process</li><li><code>nethogs</code> — Network usage per process</li><li><code>build-essential</code> — GCC compiler, make, etc. Required for building many packages from source</li><li><code>net-tools</code> — <code>ifconfig</code>, <code>netstat</code> commands</li><li><code>tree</code> — Display directory structure as a tree</li><li><code>jq</code> — JSON processor for the command line (amazing for API responses)</li><li><code>neofetch</code> — Shows system info beautifully</li><li><code>nano</code> — Beginner-friendly text editor (vs <code>vim</code> which has a learning curve)</li></ul><h2 id="prevent-lid-close-sleep-—-critical-for-a-laptop-server" tabindex="-1">Prevent Lid Close Sleep — Critical for a Laptop Server <a class="header-anchor" href="#prevent-lid-close-sleep-—-critical-for-a-laptop-server" aria-label="Permalink to &quot;Prevent Lid Close Sleep — Critical for a Laptop Server&quot;">​</a></h2><p>This is the most important post-install step. By default, when you close the laptop lid, Ubuntu suspends the system. Your server goes offline. Everyone loses SSH access. Bad.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/logind.conf</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Find these lines (use Ctrl+W to search in nano) and change them:</p><div class="language-ini vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Change these from their defaults to &#39;ignore&#39;:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HandleLidSwitch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=ignore</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HandleLidSwitchExternalPower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=ignore</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HandleLidSwitchDocked</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=ignore</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IdleAction</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=ignore</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IdleActionSec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=30min</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Save with <code>Ctrl+O</code>, then <code>Enter</code>, then exit with <code>Ctrl+X</code>.</p><p>Apply the changes:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd-logind</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Why does this work?</strong> <code>logind</code> is the service that manages user sessions and handles hardware events like lid switches, power buttons. By setting all lid actions to <code>ignore</code>, we tell it &quot;do nothing when the lid closes&quot;. The <code>systemd-logind</code> restart applies the new config immediately without rebooting.</p></div><h2 id="set-hostname" tabindex="-1">Set Hostname <a class="header-anchor" href="#set-hostname" aria-label="Permalink to &quot;Set Hostname&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hostnamectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-hostname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> homelab</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Then add it to <code>/etc/hosts</code>:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/hosts</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Add this line:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>127.0.1.1    homelab</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Why?</strong> Without this, some commands that try to resolve the hostname (like <code>sudo</code>) will produce warnings like &quot;unable to resolve host homelab&quot;. It&#39;s a cosmetic issue but annoying.</p></div><h2 id="set-timezone" tabindex="-1">Set Timezone <a class="header-anchor" href="#set-timezone" aria-label="Permalink to &quot;Set Timezone&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List available timezones</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">timedatectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list-timezones</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Africa</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set yours (Morocco/Algeria area)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> timedatectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-timezone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Africa/Casablanca</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> timedatectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-timezone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Africa/Algiers</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Verify</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">timedatectl</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Why does timezone matter?</strong> Log files, cron jobs, and database timestamps all use system time. If your timezone is wrong, <code>2026-05-19 02:00:00</code> in your logs might actually mean 1:00 AM or 3:00 AM. Debugging becomes a nightmare.</p></div><h2 id="configure-nano-as-default-editor" tabindex="-1">Configure nano as Default Editor <a class="header-anchor" href="#configure-nano-as-default-editor" aria-label="Permalink to &quot;Configure nano as Default Editor&quot;">​</a></h2><p>Many server tools open a text editor. Make sure nano is the default (easier than vim):</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-alternatives</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> editor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/bin/nano</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;export EDITOR=nano&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bashrc</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bashrc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div>`,34)])])}const u=i(t,[["render",l]]);export{k as __pageData,u as default};
